        "Python": "def test_adjacent_bookings_are_allowed():\n    bookings = [{'room': 'A', 'date': '2026-04-01', 'start': '10:00', 'end': '11:30'}]\n    assert can_book(bookings, 'A', '2026-04-01', '11:30', '12:00') is True",
        "Java": "@Test\nvoid adjacentBookingsAreAllowed() {\n    List<Booking> bookings = List.of(new Booking(\"A\", \"2026-04-01\", \"10:00\", \"11:30\"));\n    assertTrue(Rooms.canBook(bookings, \"A\", \"2026-04-01\", \"11:30\", \"12:00\"));\n}",
