        "Ruby": "class CanBookTest < Minitest::Test\n  def test_adjacent_bookings_are_allowed\n    bookings = [{ room: 'A', date: '2026-04-01', start: '10:00', end: '11:30' }]\n    assert_equal true, can_book(bookings, 'A', '2026-04-01', '11:30', '12:00')\n  end\nend",
