        "C#": "[Fact]\npublic void AdjacentBookingsAreAllowed()\n{\n    var bookings = new List<Booking> { new Booking(\"A\", \"2026-04-01\", \"10:00\", \"11:30\") };\n    Assert.Equal(true, Rooms.CanBook(bookings, \"A\", \"2026-04-01\", \"11:30\", \"12:00\"));\n}",
        "Kotlin": "@Test\nfun `終わりと始まりが接する予約は取れる`() {\n    val bookings = listOf(Booking(\"A\", \"2026-04-01\", \"10:00\", \"11:30\"))\n    assertEquals(true, canBook(bookings, \"A\", \"2026-04-01\", \"11:30\", \"12:00\"))\n}",
        "Swift": "func testAdjacentBookingsAreAllowed() {\n    let bookings = [Booking(room: \"A\", date: \"2026-04-01\", start: \"10:00\", end: \"11:30\")]\n    XCTAssertEqual(canBook(bookings, \"A\", \"2026-04-01\", \"11:30\", \"12:00\"), true)\n}"
