        "JavaScript": "test('一度引いた率は、別の表を渡しても変わらない', () => {\n  expect(convert(10, 'USD', { 'USD>JPY': 150 })).toBe(1470);\n  expect(convert(10, 'USD', { 'USD>JPY': 140 })).toBe(1470);\n});",
        "Python": "def test_cached_rate_ignores_a_different_table():\n    assert convert(10, 'USD', {'USD>JPY': 150}) == 1470\n    assert convert(10, 'USD', {'USD>JPY': 140}) == 1470",
        "Java": "@Test\nvoid cachedRateIgnoresADifferentTable() {\n    assertEquals(1470L, Exchange.convert(10, \"USD\", Map.of(\"USD>JPY\", 150.0)));\n    assertEquals(1470L, Exchange.convert(10, \"USD\", Map.of(\"USD>JPY\", 140.0)));\n}",
        "Go": "func TestCachedRateIgnoresADifferentTable(t *testing.T) {\n\tif got, _ := convert(10, \"USD\", map[string]float64{\"USD>JPY\": 150}); got != 1470 {\n\t\tt.Errorf(\"convert() = %d, want 1470\", got)\n\t}\n\tif got, _ := convert(10, \"USD\", map[string]float64{\"USD>JPY\": 140}); got != 1470 {\n\t\tt.Errorf(\"convert() with another table = %d, want 1470\", got)\n\t}\n}",
        "Ruby": "class ConvertTest < Minitest::Test\n  def test_cached_rate_ignores_a_different_table\n    assert_equal 1470, convert(10, 'USD', { 'USD>JPY' => 150 })\n    assert_equal 1470, convert(10, 'USD', { 'USD>JPY' => 140 })\n  end\nend",
        "Rust": "#[test]\nfn cached_rate_ignores_a_different_table() {\n    assert_eq!(convert(10.0, \"USD\", &BTreeMap::from([(\"USD>JPY\", 150.0)])), Some(1470.0));\n    assert_eq!(convert(10.0, \"USD\", &BTreeMap::from([(\"USD>JPY\", 140.0)])), Some(1470.0));\n}",
        "C#": "[Fact]\npublic void CachedRateIgnoresADifferentTable()\n{\n    Assert.Equal(1470L, Exchange.Convert(10, \"USD\", new Dictionary<string, double> { [\"USD>JPY\"] = 150 }));\n    Assert.Equal(1470L, Exchange.Convert(10, \"USD\", new Dictionary<string, double> { [\"USD>JPY\"] = 140 }));\n}",
        "Kotlin": "@Test\nfun `一度引いた率は、別の表を渡しても変わらない`() {\n    assertEquals(1470L, convert(10, \"USD\", mapOf(\"USD>JPY\" to 150.0)))\n    assertEquals(1470L, convert(10, \"USD\", mapOf(\"USD>JPY\" to 140.0)))\n}",
        "Swift": "func testCachedRateIgnoresADifferentTable() {\n    XCTAssertEqual(convert(10, \"USD\", [\"USD>JPY\": 150]), 1470)\n    XCTAssertEqual(convert(10, \"USD\", [\"USD>JPY\": 140]), 1470)\n}"
